#!/usr/bin/env bash
# Repack G2P on JuiceFS using local data-disk assets only (no GitHub).
set -euo pipefail
JUICE_ROOT="${MELO_JUICE_ROOT:-/mnt/data/fanyi/phanthymotus_tts}"
ASSETS_NAME="melo-openepd-g2p-assets"
TAR="${JUICE_ROOT}/${ASSETS_NAME}.tar.bz2"
CKPT=""
for c in \
  "${JUICE_ROOT}/checkpoint20.npz" \
  "/mnt/data/fanyi/tts/g2p/checkpoint20.npz"
do
  if [[ -f "$c" ]]; then CKPT="$c"; break; fi
done
[[ -n "$CKPT" ]] || { echo "missing checkpoint20.npz on data disk"; exit 1; }
[[ -f "$TAR" ]] || { echo "missing $TAR"; exit 1; }

WORK="/tmp/repack_melo_g2p_$$"
TEXT_SRC=""
# Prefer slim sources already on data disk / melo tree
for d in \
  "/mnt/data/fanyi/melo_training/repos/MeloTTS/melo/text" \
  "/mnt/data/fanyi/jushen_tts/repos/MeloTTS/melo/text"
do
  if [[ -f "$d/slim_g2p_oov.py" && -f "$d/english.py" ]]; then
    if grep -q 'slim_g2p_oov\|predict_oov' "$d/english.py"; then
      TEXT_SRC="$d"
      break
    fi
  fi
done

mkdir -p "$WORK/_slim"
if [[ -n "$TEXT_SRC" ]]; then
  echo "using slim py from $TEXT_SRC"
  cp -a "$TEXT_SRC/english.py" "$WORK/_slim/english.py"
  cp -a "$TEXT_SRC/slim_g2p_oov.py" "$WORK/_slim/slim_g2p_oov.py"
else
  echo "melo tree has no slim py; decoding embedded copies"
  base64 -d > "$WORK/_slim/english.py" <<'B64EN'

B64EN
  base64 -d > "$WORK/_slim/slim_g2p_oov.py" <<'B64SLIM'

B64SLIM
fi

echo "== extract $TAR =="
tar -xjf "$TAR" -C "$WORK"
PKG="${WORK}/${ASSETS_NAME}"
if [[ ! -d "$PKG" ]]; then
  PKG=$(find "$WORK" -maxdepth 1 -mindepth 1 -type d ! -name '_slim' | head -1)
fi
TEXT="${PKG}/vendor/melo_g2p/text"
[[ -d "$TEXT" ]] || { echo "bad tar layout: $TEXT"; exit 1; }

echo "== overlay (ckpt=$CKPT) =="
cp -a "$WORK/_slim/english.py" "$TEXT/english.py"
cp -a "$WORK/_slim/slim_g2p_oov.py" "$TEXT/slim_g2p_oov.py"
cp -a "$CKPT" "$TEXT/checkpoint20.npz"
if grep -E 'from g2p_en import|_g2p = G2p' "$TEXT/english.py"; then
  echo "ERROR: english.py still imports g2p_en"
  exit 1
fi
ls -lah "$TEXT/english.py" "$TEXT/slim_g2p_oov.py" "$TEXT/checkpoint20.npz"

ts=$(date +%Y%m%d_%H%M%S)
cp -a "$TAR" "${TAR}.bak_${ts}"
rm -f "$TAR"
tar -C "$WORK" -cjf "$TAR" "$(basename "$PKG")"
ls -lah "$TAR"
echo "== HTTP =="
curl -sI --noproxy '*' \
  "http://172.28.4.81:34567/fanyi/phanthymotus_tts/${ASSETS_NAME}.tar.bz2" | head -5
echo OK
rm -rf "$WORK"
